import manifest from './story-assets.json';

/**
 * Generated by `node scripts/build-story-assets.mjs` from the pottery renders. Every entry may be
 * missing (e.g. renders not built yet); the homepage then falls back to simpler layouts.
 */
export interface Responsive {
  src: string;
  srcSet: string;
  width: number;
  height: number;
}

export interface StoryAssets {
  version: string;
  available: boolean;
  hero: { pot: Responsive; shadow: Responsive; alt: string } | null;
  sequence: {
    desktop: string[];
    mobile: string[];
    width: number;
    height: number;
    mobileWidth: number;
    mobileHeight: number;
  } | null;
  collection: (Responsive & { alt: string }) | null;
  textures: (Responsive & { alt: string; title: string; caption: string })[];
}

export const storyAssets = manifest as unknown as StoryAssets;
